{
  "sop_id": "SOP-021",
  "title": "Employee Document Verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check completeness of role-specific document checklist",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify readability of all documents",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Verify identity and address proofs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Send education and employment confirmations to issuing institutions or background-verification agency",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for external confirmation (education/employment)",
      "role": "System",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Cross-check names, dates, grade, and salary with offer letter and HRMS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Record verification status",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Submit ticket for approval",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct discrepancies and resubmit",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (if discrepancy found)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if any discrepancy found"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Issuing Institutions / Background-Verification Agency",
      "item": "Education and employment confirmations",
      "parallel_group": null
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.90
}
